"use client";

import { useMemo, useState } from "react";
import { AlertTriangle, Bot, Cable, CheckCircle2, Database, Megaphone, Search, Settings2, Unplug, Workflow } from "lucide-react";
import { toast } from "sonner";
import type { Integration, IntegrationStatus } from "@/types/chatbot";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

interface Props { integrations: Integration[]; isBusy: boolean; onUpdate: (id: string, status: IntegrationStatus) => Promise<void> }
const categoryIcons = { channel: Cable, ai: Bot, marketing: Megaphone, automation: Workflow, data: Database };

export function IntegrationsWorkspace({ integrations, isBusy, onUpdate }: Props) {
  const [search, setSearch] = useState(""); const [category, setCategory] = useState("all"); const [selected, setSelected] = useState<Integration | null>(null);
  const visible = useMemo(() => integrations.filter((item) => (category === "all" || item.category === category) && item.name.toLowerCase().includes(search.toLowerCase())), [integrations, search, category]);
  async function simulate(status: IntegrationStatus) { if (!selected) return; try { await onUpdate(selected.id, status); toast.success(status === "connected" ? "Conexão simulada nesta sessão" : "Integração desconectada na simulação"); setSelected(null); } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível alterar a integração."); } }
  return <div className="space-y-4 p-4 md:p-5" data-testid="chatbot-integrations"><header><h2 className="text-lg font-semibold text-white">Integrações</h2><p className="text-sm text-slate-400">Catálogo real mapeado no ChatbotX; conexões permanecem cenográficas.</p></header>
    <div className="flex flex-col gap-2 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-500" /><Input value={search} onChange={(e) => setSearch(e.target.value)} aria-label="Pesquisar integrações" placeholder="Pesquisar integração" className="border-white/10 bg-slate-950/60 pl-9 text-white" /></label><Select value={category} onValueChange={setCategory}><SelectTrigger className="border-white/10 bg-slate-950/60 text-white sm:w-48"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas categorias</SelectItem><SelectItem value="channel">Canais</SelectItem><SelectItem value="ai">Inteligência artificial</SelectItem><SelectItem value="marketing">Marketing</SelectItem><SelectItem value="automation">Automação</SelectItem><SelectItem value="data">Dados</SelectItem></SelectContent></Select></div>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4">{visible.map((integration) => { const Icon = categoryIcons[integration.category]; return <article key={integration.id} className="flex min-h-44 flex-col rounded-xl border border-white/10 bg-slate-950/60 p-4 transition-colors hover:border-indigo-400/30"><header className="flex items-start justify-between gap-2"><div className="grid size-10 place-items-center rounded-lg bg-indigo-400/10 text-indigo-300"><Icon className="size-5" /></div><Status status={integration.status} /></header><h3 className="mt-3 font-semibold text-white">{integration.name}</h3><p className="mt-1 flex-1 text-xs leading-5 text-slate-400">{integration.description}</p><Button variant="outline" size="sm" disabled={isBusy} className="mt-3 w-full" onClick={() => setSelected(integration)}><Settings2 className="mr-2 size-4" />{integration.status === "connected" ? "Gerenciar" : "Configurar"}</Button></article>; })}</div>
    <Dialog open={Boolean(selected)} onOpenChange={(open) => { if (!open && !isBusy) setSelected(null); }}><DialogContent className="border-white/10 bg-slate-950 text-white"><DialogHeader><DialogTitle>{selected?.name}</DialogTitle><DialogDescription className="text-slate-400">Demonstração visual — não informe tokens, chaves, senhas ou credenciais.</DialogDescription></DialogHeader>{selected && <div className="space-y-4" aria-busy={isBusy}><div className="rounded-lg border border-amber-400/20 bg-amber-400/5 p-3 text-sm text-amber-100"><AlertTriangle className="mr-2 inline size-4" />OAuth e testes de conexão estão desabilitados nesta fase.</div><div className="grid gap-3"><Input disabled value="Credenciais serão configuradas pelo backend futuro" aria-label="Configuração futura" className="border-white/10 bg-slate-900 text-slate-500" /><div className="flex justify-end gap-2">{selected.status === "connected" ? <Button variant="destructive" disabled={isBusy} onClick={() => { void simulate("disconnected"); }}><Unplug className="mr-2 size-4" />{isBusy ? "Salvando…" : "Simular desconexão"}</Button> : <Button disabled={isBusy} onClick={() => { void simulate("connected"); }}><CheckCircle2 className="mr-2 size-4" />{isBusy ? "Salvando…" : "Simular conexão"}</Button>}</div></div></div>}</DialogContent></Dialog>
  </div>;
}
function Status({ status }: { status: IntegrationStatus }) { const spec = status === "connected" ? ["Conectado", "bg-emerald-400/10 text-emerald-300"] : status === "error" ? ["Erro", "bg-red-400/10 text-red-300"] : status === "required" ? ["Configuração necessária", "bg-amber-400/10 text-amber-300"] : ["Desconectado", "bg-slate-700 text-slate-300"]; return <Badge className={spec[1]}>{spec[0]}</Badge>; }
